function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 15) return 'grid needs 1 to 15 rows.';
  const n = grid[0].length;
  if (n < 1 || n > 15) return 'grid needs 1 to 15 columns.';
  let gold = 0;
  for (const row of grid) {
    if (!Array.isArray(row) || row.length !== n) return 'Every row must have the same length.';
    for (const v of row) {
      if (!Number.isInteger(v) || v < 0 || v > 100) return 'Each cell holds an integer from 0 to 100.';
      if (v > 0) gold++;
    }
  }
  if (gold > 25) return 'At most 25 cells may contain gold.';
  return null;
}

