function getMaximumGold(grid) {
  // Explore every (set of visited gold cells, last cell) state once; a state's gold is the sum of its set.
  const cells = [];
  grid.forEach((row, r) => row.forEach((v, c) => { if (v > 0) cells.push([r, c, v]); }));
  const id = new Map(cells.map(([r, c], i) => [`${r},${c}`, i]));
  const adj = cells.map(([r, c]) => [[r + 1, c], [r - 1, c], [r, c + 1], [r, c - 1]]
    .map(([x, y]) => id.get(`${x},${y}`)).filter(v => v !== undefined));
  let best = 0;
  const seen = new Set();
  const stack = cells.map((cell, i) => [1 << i, i, cell[2]]);
  while (stack.length) {
    const [mask, end, sum] = stack.pop();
    const key = mask * 32 + end;
    if (seen.has(key)) continue;
    seen.add(key);
    if (sum > best) best = sum;
    for (const next of adj[end]) if (!(mask & (1 << next))) stack.push([mask | (1 << next), next, sum + cells[next][2]]);
  }
  return best;
}

