function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const m = int(1, 4), n = int(1, 4);
    const density = rand();
    const top = rand() < 0.3 ? 3 : 100;
    return [Array.from({ length: m }, () => Array.from({ length: n }, () => (rand() < density ? int(1, top) : 0)))];
  }
  // Grow up to 25 gold cells as clusters on a big grid; extra links that would close loops are often refused,
  // which keeps the number of walks (and the search time) moderate.
  const m = int(10, 15), n = int(10, 15);
  const grid = Array.from({ length: m }, () => new Array(n).fill(0));
  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  const cells = [];
  const add = (r, c) => { grid[r][c] = int(1, 100); cells.push([r, c]); };
  add(int(0, m - 1), int(0, n - 1));
  for (let tries = 0; cells.length < 25 && tries < 5000; tries++) {
    if (rand() < 0.1) {
      const r = int(0, m - 1), c = int(0, n - 1);
      if (!grid[r][c]) add(r, c);
      continue;
    }
    const [r, c] = cells[int(0, cells.length - 1)];
    const [dr, dc] = dirs[int(0, 3)];
    const nr = r + dr, nc = c + dc;
    if (nr < 0 || nc < 0 || nr >= m || nc >= n || grid[nr][nc]) continue;
    let neighbours = 0;
    for (const [a, b] of dirs) { const x = nr + a, y = nc + b; if (x >= 0 && y >= 0 && x < m && y < n && grid[x][y]) neighbours++; }
    if (neighbours > 1 && rand() < 0.85) continue;
    add(nr, nc);
  }
  return [grid];
}
